function hrDashboardView(d,o){const pendingLeave=o.leaveRequests.filter(x=>["pending","manager_review"].includes(x.status)).length,pendingCorrections=o.attendanceCorrections.filter(x=>x.status==="pending").length;return `${hrOperationsHeader("Хүний нөөцийн хянах самбар","Ажилтан, хөдөлгөөн, цагийн хүсэлт болон анхаарах хугацааг нэг дор харна.")}${administrationCards([["Нийт ажилтан",d.summary.total_employees||d.employees.length],["Идэвхтэй",d.summary.active_employees],["Хүлээгдэж буй чөлөө",pendingLeave],["Ирцийн залруулга",pendingCorrections],["Дуусах гэрээ",d.summary.contracts_expiring,"warn"]])}<section class="admin-panel hr-dashboard-actions"><div class="panel-head"><div><h2>Шуурхай ажил</h2><span>Тухайн ажлын хэсэг рүү шууд шилжинэ</span></div></div><div class="hr-quick-grid"><button type="button" data-hr-tab="employees"><strong>Ажилтны бүртгэл</strong><span>Хувийн хэрэг, гэрээ, баримт</span></button><button type="button" data-hr-tab="structure"><strong>Байгууллагын бүтэц</strong><span>Нэгж, албан тушаал</span></button><button type="button" data-hr-tab="transitions"><strong>Хөдөлмөрийн харилцаа</strong><span>Томилгоо, шилжилт, гаралт</span></button><button type="button" data-hr-tab="time"><strong>Цаг ба чөлөө</strong><span>Хүсэлт, залруулга, хуваарь</span></button></div></section><section class="admin-panel"><div class="panel-head"><h2>Анхаарах хугацаа</h2><span>${o.alerts.length}</span></div><div class="admin-table-wrap"><table><thead><tr><th>Төрөл</th><th>Ажилтан</th><th>Хугацаа</th><th>Лавлагаа</th></tr></thead><tbody>${o.alerts.map(x=>`<tr><td>${x.alert_type==="contract_expiry"?"Гэрээ":"Үнэмлэх"}</td><td>${esc(x.full_name)}</td><td>${adminDate(x.due_date)}</td><td>${esc(x.reference||"—")}</td></tr>`).join("")||'<tr><td colspan="4">Анхааруулга алга.</td></tr>'}</tbody></table></div></section>`}
hrAdministration=function(d){const o=d.operations||{leaveRequests:[],attendanceCorrections:[],schedules:[],scheduleAssignments:[],organizationSkills:[],skills:[],training:[],performanceReviews:[],transitionChecklists:[],alerts:[]},area=state.hrRegistry.area||"dashboard",section=state.domainSections.hr||"dashboard";if(area==="dashboard")return hrDashboardView(d,o);if(area==="structure")return hrStructureSection(d,["structure","units","positions"].includes(section)?section:"structure");if(area==="transitions"&&section==="transfers")return hrTransferCasesView(d);if(area==="transitions"&&section==="discipline")return hrDisciplineCasesView(d);if(area==="transitions"&&["appointments","exits"].includes(section))return hrGovernedCasesView(d);if(area==="employees"){state.hrRegistry.tab="employees";return hrAdministrationV2Before(d)}if(area==="reports"){state.hrRegistry.tab="reports";return hrAdministrationV2Before(d)}if(area==="smartImport"&&section!=="migration-review"){state.hrRegistry.tab="smartImport";return hrAdministrationV2Before(d)}return hrAdministrationV2Before(d)};

hrLeaveView=function(d,o){const rows=o.leaveRequests.map(x=>`<tr><td>${esc(x.employee_name)}</td><td>${esc(x.leave_type)}</td><td>${adminDate(x.starts_on)} — ${adminDate(x.ends_on)}</td><td>${domainBadge(x.status)}</td><td><div class="domain-actions">${["pending","manager_review"].includes(x.status)?`<button data-domain-command="approve" data-domain="leave" data-id="${x.id}" data-version="${x.version||0}">Батлах</button><button data-domain-command="return" data-domain="leave" data-id="${x.id}" data-version="${x.version||0}">Буцаах</button><button data-domain-command="reject" data-domain="leave" data-id="${x.id}" data-version="${x.version||0}">Татгалзах</button>`:""}</div></td></tr>`).join("");return `${hrOperationsHeader("Чөлөө, амралт","Тохируулгатай routing, давхцлын шалгалт, version guard, audit ба notification intent ашиглана.")}<form id="hrLeaveForm" class="admin-form"><div class="admin-fields"><label>Ажилтан<select name="employeeId">${hrEmployeeOptions(d)}</select></label><label>Төрөл<select name="leaveType"><option value="annual">Ээлжийн амралт</option><option value="sick">Өвчтэй</option><option value="unpaid">Цалингүй</option><option value="family">Гэр бүлийн</option><option value="other">Бусад</option></select></label><label>Эхлэх<input name="startsOn" type="date" required></label><label>Дуусах<input name="endsOn" type="date" required></label><label>Өдөр<input name="requestedDays" type="number" min="0.5" step="0.5" required></label></div><label>Шалтгаан<input name="reason" required></label><button class="primary">Хүсэлт илгээх</button></form><section class="admin-panel"><div class="admin-table-wrap"><table><thead><tr><th>Ажилтан</th><th>Төрөл</th><th>Хугацаа</th><th>Төлөв</th><th>Үйлдэл</th></tr></thead><tbody>${rows||'<tr><td colspan="5">Хүсэлт алга.</td></tr>'}</tbody></table></div></section>`};

document.addEventListener("submit",async event=>{const form=event.target;if(!["recordsV2Form","complaintForm","archiveV2Form","archiveAccessForm","appointmentForm","exitCaseForm","transferCaseForm"].includes(form.id))return;event.preventDefault();const data=new FormData(form),v=Object.fromEntries(data);Object.keys(v).forEach(k=>{if(v[k]==="")delete v[k]});v.idempotencyKey=crypto.randomUUID();let endpoint="";if(form.id==="recordsV2Form"){endpoint="/api/records";v.priority="normal";v.documentIds=[]}if(form.id==="complaintForm"){endpoint="/api/complaints";v.documentIds=[]}if(form.id==="archiveV2Form"){endpoint="/api/archive";v.permanent=false;v.retentionYears=10}if(form.id==="archiveAccessForm")endpoint="/api/archive/access-requests";if(form.id==="appointmentForm"){endpoint="/api/hr/appointments";v.candidateIdentity={};v.requirements=String(v.requirements||"").split("\n").map((title,index)=>({code:`requirement-${index+1}`,title:title.trim(),required:true})).filter(x=>x.title);delete v.requirements}if(form.id==="exitCaseForm"){endpoint="/api/hr/exit-cases";v.handoverItems=String(v.handoverItems||"").split("\n").map(title=>({itemType:"other",title:title.trim(),required:true})).filter(x=>x.title);delete v.handoverItems}if(form.id==="transferCaseForm"){endpoint="/api/hr/transfer-cases";v.consentRequired=data.has("consentRequired");v.policySnapshot={source:"tenant_case_review",legalBasisReference:v.legalBasisReference,consentRequired:v.consentRequired};}try{await api(endpoint,{method:"POST",body:JSON.stringify(v)});form.reset();state.administration[state.view]=null;await loadAdministration(state.view);toast("Бүртгэл серверээр баталгаажлаа")}catch(error){toast(error.message,true)}});

document.addEventListener("click",async event=>{
  const close=event.target.closest("[data-domain-detail-close]"),open=event.target.closest("[data-domain-open]"),assign=event.target.closest("[data-domain-assign]"),command=event.target.closest("[data-domain-command]"),handoff=event.target.closest("[data-complaint-hr-handoff]");
  if(close){state.domainDetail=null;renderAdministration(state.view);return}
  try{
    if(open&&!event.target.closest("button")){state.domainDetail=await api(`/api/${open.dataset.domainOpen}/${open.dataset.id}`);renderAdministration(state.view);return}
    if(assign){const userName=prompt("Хариуцагчийн нэр:","");if(userName===null)return;const user=state.assignableUsers.find(x=>x.full_name.toLocaleLowerCase("mn-MN")===userName.trim().toLocaleLowerCase("mn-MN"));if(!user)throw new Error("Хариуцагчийн нэр олдсонгүй");await api(`/api/${assign.dataset.domainAssign}/${assign.dataset.id}/assign`,{method:"POST",body:JSON.stringify({expectedVersion:Number(assign.dataset.version),assigneeUserId:user.id,reason:"UI хуваарилалт",idempotencyKey:crypto.randomUUID()})})}
    if(handoff){const subjectReference=prompt("Холбогдох ажилтан / албан тушаалын лавлагаа:","");if(subjectReference===null||!subjectReference.trim())return;const reason=prompt("HR яагаад тусдаа сахилгын хэрэг шаардлагатай эсэхийг шалгах вэ?","");if(reason===null||!reason.trim())return;await api(`/api/complaints/${handoff.dataset.complaintHrHandoff}/hr-handoffs`,{method:"POST",body:JSON.stringify({expectedVersion:Number(handoff.dataset.version),subjectReference,reason,documentIds:[],idempotencyKey:crypto.randomUUID()})})}
    if(command){const domain=command.dataset.domain,reason=prompt("Үндэслэл / тайлбар:","");if(reason===null||!reason.trim())return;const body={expectedVersion:Number(command.dataset.version),reason,idempotencyKey:crypto.randomUUID()},findDocument=label=>{const number=prompt(label,"");const doc=state.administration.hr?.documents?.find(x=>x.document_no===number);if(!doc)throw new Error("Canonical баримт олдсонгүй");return doc};if(["submit_response","approve_response"].includes(command.dataset.domainCommand)){const number=prompt("Хариу баримтын дугаар:","");const doc=state.administration[state.view]?.documents?.find(x=>x.document_no===number);if(!doc)throw new Error("Canonical хариу баримт олдсонгүй");body.responseDocumentId=doc.id;body.resolution=reason}if(command.dataset.domainCommand==="send_response"){body.recipient=prompt("Хүлээн авагч:","")||"";body.deliveryReference=prompt("Хүргэлтийн нотолгооны дугаар:","")||""}if(command.dataset.domainCommand==="finalize"&&["appointment","exit"].includes(domain))body.orderDocumentId=findDocument("Тушаалын canonical баримтын дугаар:").id;if(domain==="transfer"&&command.dataset.domainCommand==="record_consent"){body.consentStatus="provided";body.consentDocumentId=findDocument("Ажилтны зөвшөөрлийн canonical баримтын дугаар:").id}if(domain==="transfer"&&command.dataset.domainCommand==="management_review"){body.workloadAssessment=reason;body.proposalDocumentId=findDocument("Шилжилтийн саналын canonical баримтын дугаар:").id}if(domain==="transfer"&&command.dataset.domainCommand==="approve")body.decisionDocumentId=findDocument("Шийдвэр / тушаалын canonical баримтын дугаар:").id;const base={appointment:"/api/hr/appointments",exit:"/api/hr/exit-cases",transfer:"/api/hr/transfer-cases",leave:"/api/hr/leave-requests",records:"/api/records",complaints:"/api/complaints",archive:"/api/archive"}[domain];await api(`${base}/${command.dataset.id}/commands/${command.dataset.domainCommand}`,{method:"POST",body:JSON.stringify(body)})}
    if(assign||command||handoff){state.administration[state.view]=null;await loadAdministration(state.view);toast("Үйлдэл серверээр баталгаажлаа")}
  }catch(error){toast(error.message,true)}
});

// Archive access and disposal are rendered as governed sub-workspaces. They
// deliberately remain separate from the ordinary archive-record command bar.
const archivePhase2Base=archiveAdministration;
archiveAdministration=function(d){
  const base=archivePhase2Base(d),section=state.domainSections.archive||"dashboard",permissions=new Set(state.permissions||[]);
  if(section==="access"){
    const action=x=>({requested:[["approve","Зөвшөөрөх"],["reject","Татгалзах"]],approved:[["issue","Олгох"]],issued:[["return","Буцаан авах"]]}[x.status]||[]).map(([command,label])=>`<button data-archive-access-command="${command}" data-id="${x.id}" data-version="${x.version}">${label}</button>`).join("");
    return `${base}<section class="admin-panel"><div class="panel-head"><h2>Ашиглалт, олголт, буцаалт</h2><span>${d.accessRequests?.length||0} хүсэлт</span></div><div class="admin-table-wrap"><table><thead><tr><th>Баримт</th><th>Хүсэлт гаргагч</th><th>Зорилго</th><th>Төлөв</th><th>Буцаах</th><th>Үйлдэл</th></tr></thead><tbody>${(d.accessRequests||[]).map(x=>`<tr><td>${esc(x.archive_no)}<small>${esc(x.title)}</small></td><td>${esc(x.requester_name)}</td><td>${esc(x.purpose)}</td><td>${domainBadge(x.status)}</td><td>${dateTime(x.due_back_at)}</td><td><div class="domain-actions">${permissions.has("archive.access.manage")?action(x):""}</div></td></tr>`).join("")||'<tr><td colspan="6" class="domain-empty">Ашиглалтын хүсэлт алга.</td></tr>'}</tbody></table></div></section>`;
  }
  if(["proposals","commission","acts"].includes(section)){
    const candidates=(d.items||[]).filter(x=>["retention_review","due_for_disposal"].includes(x.status));
    const visible=(d.destructionProposals||[]).filter(x=>section==="proposals"||section==="commission"&&["proposed","commission_review","approved","rejected"].includes(x.status)||section==="acts"&&["approved","executed","verified"].includes(x.status));
    const buttons=x=>{const rules={proposed:["commission_review","Комисст оруулах","archive.destruction.approve"],commission_review:["approve","Батлах","archive.destruction.approve"],approved:["execute","Устгал гүйцэтгэх","archive.disposal.execute"],executed:["verify","Тусдаа этгээд баталгаажуулах","archive.disposal.verify"]},rule=rules[x.status];return rule&&permissions.has(rule[2])?`<button data-archive-proposal-command="${rule[0]}" data-id="${x.id}" data-version="${x.version}" data-hash="${esc(String(x.item_set_sha256||"").trim())}">${rule[1]}</button>${x.status==="commission_review"?`<button data-archive-proposal-command="reject" data-id="${x.id}" data-version="${x.version}">Татгалзах</button>`:""}`:""};
    return `${base}${section==="proposals"&&permissions.has("archive.retention.review")?`<form class="admin-form" id="archiveProposalForm"><h2>Устгах санал үүсгэх</h2><label>Хадгалалтын хяналт дууссан баримт<select name="archiveRecordId" required>${candidates.map(x=>`<option value="${x.id}">${esc(x.archive_no)} · ${esc(x.title)}</option>`).join("")}</select></label><label>Үндэслэл<textarea name="reason" required></textarea></label><label>Гадаад зөвшөөрлийн лавлагаа<input name="externalApprovalReference"></label><p class="domain-danger-note">Санал нь устгал биш. Комисс, гүйцэтгэгч, тусдаа баталгаажуулагчийн серверээр баталгаажсан шат шаардлагатай.</p><button class="primary" ${candidates.length?"":"disabled"}>Санал үүсгэх</button></form>`:""}<section class="admin-panel"><div class="panel-head"><h2>${section==="commission"?"Комиссын шийдвэр":section==="acts"?"Устгах акт ба баталгаа":"Устгах санал"}</h2><span>${visible.length}</span></div><div class="admin-table-wrap"><table><thead><tr><th>Санал</th><th>Баримт</th><th>Үндэслэл</th><th>Төлөв</th><th>Үйлдэл</th></tr></thead><tbody>${visible.map(x=>`<tr><td>${esc(x.proposal_no)}</td><td>${esc(x.archive_no)}<small>${esc(x.title)}</small></td><td>${esc(x.reason)}</td><td>${domainBadge(x.status)}</td><td><div class="domain-actions">${buttons(x)}</div></td></tr>`).join("")||'<tr><td colspan="5" class="domain-empty">Тохирох санал алга.</td></tr>'}</tbody></table></div></section>`;
  }
  return base;
};

async function sha256Hex(value){const bytes=await crypto.subtle.digest("SHA-256",new TextEncoder().encode(value));return [...new Uint8Array(bytes)].map(x=>x.toString(16).padStart(2,"0")).join("")}
document.addEventListener("submit",async event=>{if(event.target.id!=="archiveProposalForm")return;event.preventDefault();const body=Object.fromEntries(new FormData(event.target));body.idempotencyKey=crypto.randomUUID();body.itemSetSha256=await sha256Hex(JSON.stringify({archiveRecordId:body.archiveRecordId,reason:body.reason}));try{await api("/api/archive/destruction-proposals",{method:"POST",body:JSON.stringify(body)});state.administration.archive=null;await loadAdministration("archive");toast("Устгах санал серверээр бүртгэгдлээ")}catch(error){toast(error.message,true)}});
document.addEventListener("click",async event=>{const access=event.target.closest("[data-archive-access-command]"),proposal=event.target.closest("[data-archive-proposal-command]");if(!access&&!proposal)return;event.preventDefault();event.stopPropagation();try{const reason=prompt("Үндэслэл / тайлбар:","");if(!reason?.trim())return;const body={expectedVersion:Number((access||proposal).dataset.version),reason,idempotencyKey:crypto.randomUUID()};let endpoint;if(access)endpoint=`/api/archive/access-requests/${access.dataset.id}/commands/${access.dataset.archiveAccessCommand}`;else{const command=proposal.dataset.archiveProposalCommand;endpoint=`/api/archive/destruction-proposals/${proposal.dataset.id}/commands/${command}`;if(command==="execute"){const number=prompt("Устгах актын canonical баримтын дугаар:","");const doc=state.administration.archive?.documents?.find(x=>x.document_no===number);if(!doc)throw new Error("Canonical актын баримт олдсонгүй");body.actNo=prompt("Актын дугаар:","")||"";body.actDocumentId=doc.id;body.method=prompt("Устгалын арга:","")||"";body.itemSetSha256=proposal.dataset.hash;body.evidence={serverConfirmed:true}}}await api(endpoint,{method:"POST",body:JSON.stringify(body)});state.administration.archive=null;await loadAdministration("archive");toast("Архивын үйлдэл серверээр баталгаажлаа")}catch(error){toast(error.message,true)}});

state.domainSearch=state.domainSearch||{};state.domainPages=state.domainPages||{};
const phase2AdministrationQuery=administrationQuery;
administrationQuery=function(view){const original=phase2AdministrationQuery(view),params=new URLSearchParams(original.replace(/^\?/,"")),search=String(state.domainSearch[view]||"").trim(),page=Number(state.domainPages[view]||1);if(search)params.set("search",search);if(page>1)params.set("page",String(page));return params.size?`?${params}`:""};
const phase2RenderAdministration=renderAdministration;
renderAdministration=function(view){phase2RenderAdministration(view);if(view==="hr"){document.querySelectorAll('[data-domain="appointment"],[data-domain="exit"]').forEach(button=>{const actions=button.closest(".domain-actions");if(actions&&!actions.querySelector("[data-hr-evidence-case]")){const evidence=document.createElement("button");evidence.type="button";evidence.dataset.hrEvidenceCase=button.dataset.domain;evidence.dataset.id=button.dataset.id;evidence.textContent=button.dataset.domain==="appointment"?"Баримтын бүрдэл":"Хүлээлцэх жагсаалт";actions.append(evidence)}});return}if(!["records","complaints","archive"].includes(view))return;const d=state.administration[view],anchor=document.querySelector("#pageContent .admin-panel");if(!d||!anchor)return;const page=d.pagination?.page||1,total=d.pagination?.total??d.items?.length??0,pageSize=d.pagination?.pageSize||Math.max(total,1),controls=document.createElement("form");controls.className="admin-form domain-list-tools";controls.id="domainListSearch";controls.innerHTML=`<div class="admin-fields"><label>Хайх<input name="search" value="${esc(state.domainSearch[view]||"")}" placeholder="Дугаар, гарчиг, нэр"></label></div><div class="domain-actions"><button class="primary">Хайх</button><button type="button" data-domain-search-clear>Цэвэрлэх</button><button type="button" data-domain-page="${page-1}" ${page<=1?"disabled":""}>Өмнөх</button><span>${page} / ${Math.max(1,Math.ceil(total/pageSize))}</span><button type="button" data-domain-page="${page+1}" ${page*pageSize>=total?"disabled":""}>Дараах</button></div>`;anchor.before(controls)};
document.addEventListener("submit",async event=>{if(event.target.id!=="domainListSearch")return;event.preventDefault();state.domainSearch[state.view]=new FormData(event.target).get("search")||"";state.domainPages[state.view]=1;state.administration[state.view]=null;await loadAdministration(state.view)});
document.addEventListener("click",async event=>{const clear=event.target.closest("[data-domain-search-clear]"),page=event.target.closest("[data-domain-page]");if(!clear&&!page)return;if(clear)state.domainSearch[state.view]="";if(page)state.domainPages[state.view]=Math.max(1,Number(page.dataset.domainPage)||1);state.administration[state.view]=null;await loadAdministration(state.view)});

function showHrEvidence(kind,data){document.querySelector("#hrEvidencePanel")?.remove();const panel=document.createElement("section"),items=kind==="appointment"?data.requirements:data.handoverItems;panel.id="hrEvidencePanel";panel.className="admin-panel";panel.innerHTML=`<div class="panel-head"><div><h2>${kind==="appointment"?"Шаардлагатай баримтын бүрдэл":"Хүлээлцэх ажлын жагсаалт"}</h2><span>${esc(data.item.case_no)} · ${domainBadge(data.item.status)}</span></div><button type="button" onclick="this.closest('section').remove()">Хаах</button></div><div class="admin-table-wrap"><table><thead><tr><th>Нэр</th><th>Төрөл</th><th>Нотолгоо</th><th>Төлөв</th><th>Үйлдэл</th></tr></thead><tbody>${(items||[]).map(x=>`<tr><td>${esc(x.title)}</td><td>${esc(x.requirement_code||x.item_type)}</td><td>${esc(x.document_id||x.evidence_document_id||"—")}</td><td>${kind==="appointment"?(x.verified_at?"Шалгасан":"Хүлээгдэж буй"):(x.completed_at?"Дууссан":"Хүлээгдэж буй")}</td><td><button data-hr-evidence-update="${kind}" data-case-id="${data.item.id}" data-item-id="${x.id}" data-version="${x.version}" data-complete="${kind==="appointment"?!x.verified_at:!x.completed_at}">${kind==="appointment"?(x.verified_at?"Шалгалт цуцлах":"Шалгаж батлах"):(x.completed_at?"Дахин нээх":"Дуусгах")}</button></td></tr>`).join("")||'<tr><td colspan="5">Заавал биелүүлэх item алга.</td></tr>'}</tbody></table></div>`;document.querySelector("#pageContent").append(panel);panel.scrollIntoView({behavior:"smooth",block:"start"})}
document.addEventListener("click",async event=>{const open=event.target.closest("[data-hr-evidence-case]"),update=event.target.closest("[data-hr-evidence-update]");if(!open&&!update)return;event.preventDefault();event.stopPropagation();try{if(open){const kind=open.dataset.hrEvidenceCase,data=await api(kind==="appointment"?`/api/hr/appointments/${open.dataset.id}`:`/api/hr/exit-cases/${open.dataset.id}`);showHrEvidence(kind,data);return}const kind=update.dataset.hrEvidenceUpdate,complete=update.dataset.complete==="true",body={expectedVersion:Number(update.dataset.version),note:prompt("Тайлбар:","")||""};const number=complete?prompt(kind==="appointment"?"Нотлох canonical баримтын дугаар:":"Нотлох canonical баримтын дугаар (байхгүй бол хоосон):",""):"";if(kind==="appointment"&&complete&&!number)throw new Error("Шаардлагатай баримт заавал canonical нотолгоотой байна");const doc=number?state.administration.hr?.documents?.find(x=>x.document_no===number):null;if(number&&!doc)throw new Error("Canonical баримт олдсонгүй");if(kind==="appointment"){body.verified=complete;body.documentId=doc?.id||null}else{body.completed=complete;body.evidenceDocumentId=doc?.id||null}await api(kind==="appointment"?`/api/hr/appointments/${update.dataset.caseId}/requirements/${update.dataset.itemId}`:`/api/hr/exit-cases/${update.dataset.caseId}/handover/${update.dataset.itemId}`,{method:"PATCH",body:JSON.stringify(body)});const data=await api(kind==="appointment"?`/api/hr/appointments/${update.dataset.caseId}`:`/api/hr/exit-cases/${update.dataset.caseId}`);showHrEvidence(kind,data);toast("Нотолгооны төлөв серверээр шинэчлэгдлээ")}catch(error){toast(error.message,true)}});

// Restricted disciplinary commands are handled before the shared domain
// command listener so their evidence-specific payload cannot be generalized.
document.addEventListener("submit",async event=>{const form=event.target;if(form.id!=="disciplineCaseForm")return;event.preventDefault();event.stopImmediatePropagation();const data=new FormData(form),body=Object.fromEntries(data),discipline=state.administration.hr?.discipline||{};body.idempotencyKey=crypto.randomUUID();body.fourEyesRequired=data.has("fourEyesRequired");body.policySnapshot={policyCode:body.policyCode,policyVersion:body.policyVersion,fourEyesRequired:body.fourEyesRequired,deadlineBasis:body.deadlineBasis};delete body.policyCode;delete body.policyVersion;delete body.deadlineBasis;delete body.fourEyesRequired;delete body.decisionDueOn;body.deadlineClass=body.deadlineClass||"ordinary";body.deadlineSuspensions=[];body.initialEvidenceDocumentIds=body.initialEvidenceDocumentId?[body.initialEvidenceDocumentId]:[];delete body.initialEvidenceDocumentId;if(body.sourceHandoffId){const handoff=discipline.handoffs?.find(x=>x.id===body.sourceHandoffId);body.handoffExpectedVersion=Number(handoff?.version)}else delete body.sourceHandoffId;try{await api("/api/hr/discipline-cases",{method:"POST",body:JSON.stringify(body)});form.reset();state.administration.hr=null;await loadAdministration("hr");toast("Restricted сахилгын хэрэг бүртгэгдлээ")}catch(error){toast(error.message,true)}},{capture:true});

document.addEventListener("click",async event=>{const command=event.target.closest('[data-domain="discipline"][data-domain-command]'),decline=event.target.closest("[data-discipline-handoff-decline]");if(!command&&!decline)return;event.preventDefault();event.stopImmediatePropagation();const reason=prompt("Үндэслэл / тайлбар:","");if(!reason?.trim())return;try{if(decline){await api(`/api/hr/discipline-handoffs/${decline.dataset.disciplineHandoffDecline}/decline`,{method:"POST",body:JSON.stringify({expectedVersion:Number(decline.dataset.version),reason,idempotencyKey:crypto.randomUUID()})})}else{const action=command.dataset.domainCommand,body={expectedVersion:Number(command.dataset.version),reason,idempotencyKey:crypto.randomUUID()},findDocument=label=>{const number=prompt(label,"");const doc=state.administration.hr?.documents?.find(x=>x.document_no===number);if(!doc)throw new Error("Canonical баримт олдсонгүй");return doc.id};if(action==="assign_investigator"){const name=prompt("Шалгагчийн нэр:","");const employee=state.administration.hr?.employees?.find(x=>x.full_name.toLocaleLowerCase("mn-MN")===String(name||"").trim().toLocaleLowerCase("mn-MN")&&x.user_id);if(!employee)throw new Error("Нэвтрэх эрхтэй шалгагч олдсонгүй");body.investigatorUserId=employee.user_id}if(action==="issue_notice")body.noticeDocumentId=findDocument("Мэдэгдлийн canonical баримтын дугаар:");if(action==="record_explanation"){body.explanationStatus=(prompt("Тайлбарын төлөв: provided эсвэл refused","provided")||"").trim();body.explanationDocumentId=findDocument("Тайлбар/татгалзлын canonical баримтын дугаар:")}if(action==="submit_recommendation"){body.finding=(prompt("Дүгнэлт: substantiated, unsubstantiated, insufficient_evidence","substantiated")||"").trim();body.investigationSummary=reason;body.recommendation=prompt("Шийдвэрийн санал:","")||"";body.recommendedActionCode=body.finding==="substantiated"?(prompt("Tenant policy дахь арга хэмжээний код:","")||""):"no_action";body.recommendationDocumentId=findDocument("Дүгнэлт/саналын canonical баримтын дугаар:")}if(action==="decide"){body.decisionOutcome=(prompt("Шийдвэр: sanctioned, no_action, returned","no_action")||"").trim();body.decisionDocumentId=findDocument("Шийдвэрийн canonical баримтын дугаар:");if(body.decisionOutcome==="sanctioned"){body.sanctionCode=prompt("Tenant policy дахь шийтгэлийн код:","")||"";body.effectiveFrom=prompt("Хүчинтэй эхлэх огноо YYYY-MM-DD:","")||"";body.sanctionExpiresOn=prompt("Дуусах огноо YYYY-MM-DD:","")||""}}if(action==="return")body.decisionDocumentId=findDocument("Буцаах шийдвэрийн canonical баримтын дугаар:");if(action==="acknowledge"){body.acknowledgementStatus=(prompt("Танилцуулга: provided эсвэл refused","provided")||"").trim();body.acknowledgementDocumentId=findDocument("Танилцуулсан/татгалзсан canonical баримтын дугаар:")}if(action==="early_remove")body.removalDocumentId=findDocument("Эрт арилгах шийдвэрийн canonical баримтын дугаар:");if(action==="dispute"){body.disputeReference=prompt("Маргааны лавлагаа:","")||"";body.disputeDocumentId=findDocument("Маргааны canonical баримтын дугаар:")}if(action==="resolve_dispute")body.disputeResolution=prompt("Маргааны шийдвэр:","")||"";await api(`/api/hr/discipline-cases/${command.dataset.id}/commands/${action}`,{method:"POST",body:JSON.stringify(body)})}state.administration.hr=null;await loadAdministration("hr");toast("Сахилгын үйлдэл серверээр баталгаажлаа")}catch(error){toast(error.message,true)}},{capture:true});
